def truncate_words(s, max_words):
    words = s.split()
    if max_words <= 0:
        return ""
    if len(words) <= max_words:
        return " ".join(words)
    return " ".join(words[:max_words]) + " [more]"

def initials(name):
    parts = [p for p in name.split() if p]
    return "".join(p[0].upper() for p in parts)

def count_vowels(s):
    return sum(1 for ch in s.lower() if ch in "aeiou")

