"""Initial basic (honest-but-shallow) test suite for textutils."""
from textutils.textutils import count_vowels, initials, truncate_words


class TestTruncateWords:
    def test_short_string_unchanged(self):
        assert truncate_words("hello world", 5) == "hello world"

    def test_long_string_truncated(self):
        assert truncate_words("a b c d", 2) == "a b [more]"

    def test_zero_max_words(self):
        assert truncate_words("a b", 0) == ""

    def test_negative_max_words(self):
        assert truncate_words("a b", -1) == ""


class TestInitials:
    def test_simple_name(self):
        assert initials("John Smith") == "JS"

    def test_single_name(self):
        assert initials("Madonna") == "M"


class TestCountVowels:
    def test_mixed_case(self):
        assert count_vowels("Hello World") == 3

    def test_no_vowels(self):
        assert count_vowels("xyz") == 0

